    // FAQ section
    'faq.title': 'Frequently Asked Questions',
    'faq.q1': 'How does the microtask system work?',
    'faq.a1': 'Microtasks are small activities you can perform from any device (whenever possible). Each task has a specific reward and you can complete as many as you want.',
    'faq.q2': 'How do I receive my payments?',
    'faq.a2':
      'Payments use USDC (Stellar) with on-chain escrow. Client and worker confirm in the app that the work is done; the client approves and signs the on-chain release and payment reaches your wallet (Freighter).',
    'faq.q3': 'What requirements do I need to start?',
    'faq.a3': 'You only need an internet connection and a device (computer, tablet or smartphone). No special technical knowledge is required unless specified.',
    'faq.q4': 'How does the escrow system work?',
    'faq.a4':
      'We use Stellar escrow: funds are held until the client approves delivery and signs the release; the platform does not custody your keys.',

