    'faq.title': 'Perguntas Frequentes',
    'faq.q1': 'Como funciona o sistema de microtarefas?',
    'faq.a1': 'As microtarefas são pequenas atividades que você pode realizar de qualquer dispositivo. Cada tarefa tem uma recompensa específica e você pode completar quantas quiser.',
    'faq.q2': 'Como recebo meus pagamentos?',
    'faq.a2':
      'Os pagamentos são em USDC (Stellar) com escrow na rede. Cliente e trabalhador confirmam na app que o trabalho está pronto; o cliente aprova e assina a liberação on-chain e o pagamento chega à sua carteira (Freighter).',
    'faq.q3': 'Quais requisitos preciso para começar?',
    'faq.a3': 'Só precisa de internet e um dispositivo (computador, tablet ou celular). Não é necessário conhecimento técnico especial, a menos que a tarefa exija.',
    'faq.q4': 'Como funciona o sistema de escrow?',
    'faq.a4':
      'Usamos escrow na Stellar: os fundos ficam retidos até o cliente aprovar a entrega e assinar a liberação; a plataforma não custodia suas chaves.',

